        state['progress'] += 1
        if state['progress'] == 2:
            state['outcome'] = 'won'


def render(state):
    grid = np.full((64, 64), BASE + STEP * state['progress'], dtype=np.int8)
    grid[0, :START_ENERGY] = 8
